+function extensionFromUrl(url) {
+  try {
+    const pathname = new URL(url).pathname.toLowerCase();
+    const ext = path.extname(pathname);
+    return ext && ext.length <= 6 ? ext : ".jpg";
+  } catch {
+    return ".jpg";
+  }
+}
